def solve(speed):
    """speed[h] = finishing time (smaller = faster). Returns (top3, races_used)."""
    races = [0]
    def run(hs):
        races[0] += 1
        return sorted(hs, key=lambda h: speed[h])
    groups = [run(list(range(5 * i, 5 * i + 5))) for i in range(5)]   # races 1-5
    order = run([g[0] for g in groups])                                # race 6
    rank = {g[0]: g for g in groups}
    A, B, C = rank[order[0]], rank[order[1]], rank[order[2]]
    second_third = run([A[1], A[2], B[0], B[1], C[0]])[:2]             # race 7
    final = run([A[0]] + second_third + [25, 26])                      # race 8
    return final[:3], races[0]

