class LinkedList:
    def __init__(self, vals=()):
        self.head = tail = None
        for v in vals:
            n = Node(v)
            if tail is None:
                self.head = tail = n
            else:
                tail.next = n; tail = n

    def swap(self, x, y):
        if x == y:
            return
        prev_x = prev_y = cur_x = cur_y = None
        prev, cur = None, self.head
