import random
from itertools import permutations


class Node:
    __slots__ = ("val", "next")

    def __init__(self, val, nxt=None):
        self.val, self.next = val, nxt


class LinkedList:
    def __init__(self, vals=()):
        self.head = None
        tail = None
        for v in vals:
            n = Node(v)
            if tail is None:
                self.head = tail = n
            else:
                tail.next = n
                tail = n

    def to_list(self):
        out, cur = [], self.head
        while cur:
            out.append(cur.val)
            cur = cur.next
        return out

    def swap(self, x, y):
        """Swap the first nodes holding x and y by relinking, not by copying."""
        if x == y:
            return
        prev_x = prev_y = None
        cur_x = cur_y = None
        prev, cur = None, self.head
        while cur:
            if cur.val == x and cur_x is None:
                prev_x, cur_x = prev, cur
            elif cur.val == y and cur_y is None:
                prev_y, cur_y = prev, cur
            prev, cur = cur, cur.next
        if cur_x is None or cur_y is None:
            return
        if prev_x:
            prev_x.next = cur_y
        else:
            self.head = cur_y
        if prev_y:
            prev_y.next = cur_x
        else:
            self.head = cur_x
        cur_x.next, cur_y.next = cur_y.next, cur_x.next


