from functools import lru_cache

# V(r,b) = best win prob with r red, b black left; you must bet before the deck
# runs out (equivalently the last card is a forced bet).
import sys
sys.setrecursionlimit(10000)

@lru_cache(maxsize=None)
def V(r, b):
    if r == 0:
        return F(0)
    if b == 0:
        return F(1)
    n = r + b
    stop = F(r, n)
    go = F(r, n) * V(r - 1, b) + F(b, n) * V(r, b - 1)
    return max(stop, go)

