from math import factorial


def one_pass(a):
    a = list(a)
    for i in range(len(a) - 1):
        if a[i] > a[i + 1]:
            a[i], a[i + 1] = a[i + 1], a[i]
    return a


def two_larger_before(p):          # contains pattern 231 or 321
    return any(sum(1 for x in p[:k] if x > p[k]) >= 2 for k in range(len(p)))


def from_composition(comp):        # cycle each consecutive block's max to its front
    out, start = [], 1
    for L in comp:
        blk = list(range(start, start + L))
        out += [blk[-1]] + blk[:-1]
        start += L
    return tuple(out)


def compositions(n):
    if n == 0:
        yield ()
        return
    for first in range(1, n + 1):
        for rest in compositions(n - first):
            yield (first,) + rest


