import math
from functools import lru_cache
from itertools import product

# brute-force: count ordered sequences of 1s and 2s summing to n
def brute(n):
    total = 0
    for k in range(1, n + 1):  # number of jumps
        for seq in product((1, 2), repeat=k):
            if sum(seq) == n:
                total += 1
    return total

@lru_cache(None)
def fib(k):  # F(1)=F(2)=1
    return 1 if k <= 2 else fib(k - 1) + fib(k - 2)

def binet(n):
    phi = (1 + math.sqrt(5)) / 2
    psi = (1 - math.sqrt(5)) / 2
    return (phi ** (n + 1) - psi ** (n + 1)) / math.sqrt(5)

